mapper.select:
/*selectDeptSelect*/ SELECT X.DEPT_NAME AS DEPT_NAME, -- 0 X.ACCOUNT_NAME AS ACCOUNT_NAME, -- 1 DECODE(X.AVAIL_AMT,NULL,0,X.AVAIL_AMT) AS AVAIL_AMT, -- 2 DECODE(X.AVAIL_AMT,NULL,'N','Y') AS PLAN_AMT_FLAG, -- 3 X.BDGT_FLAG AS BDGT_FLAG2, -- 4 X.DEPT_CODE AS DEPT_CODE, -- 5 X.ACCOUNT_TYPE AS ACCOUNT_TYPE, -- 6 X.PLAN_AMT, -- 7 X.RESULT_TEMP_AMT, -- 8 X.MNG_FLAG , X.MNG_DEPT_CD , X.MNG_DEPT_NM , X.MGMT_NO_REQ_YN , X.REMARK , X.VIEW_FLAG FROM ( SELECT (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = B.BUYER AND TYPE = 'C001' AND CODE = B.CODE1) AS DEPT_NAME, (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = B.BUYER AND TYPE = 'Z014' AND CODE = B.CODE2) AS ACCOUNT_NAME, PLAN_AMT - (RESULT_AMT+TEMP_AMT) AS AVAIL_AMT, (SELECT FLAG FROM ICOMCOD2 WHERE COMPANY_CODE = B.BUYER AND TYPE = 'Z014' AND CODE = B.CODE2) AS BDGT_FLAG, B.CODE1 DEPT_CODE, B.CODE2 ACCOUNT_TYPE, G.PLAN_AMT AS PLAN_AMT, (G.RESULT_AMT + G.TEMP_AMT) AS RESULT_TEMP_AMT, B.TEXT4 AS MNG_FLAG, (SELECT COD.TEXT5 FROM ICOMCOD2 COD WHERE COD.COMPANY_CODE = B.BUYER AND COD.TYPE = 'Z014' AND COD.CODE = B.CODE2) AS MNG_DEPT_CD, (SELECT COD.TEXT6 FROM ICOMCOD2 COD WHERE COD.COMPANY_CODE = B.BUYER AND COD.TYPE = 'Z014' AND COD.CODE = B.CODE2) AS MNG_DEPT_NM, (SELECT COD.TEXT4 FROM ICOMCOD2 COD WHERE COD.COMPANY_CODE = B.BUYER AND COD.TYPE = 'Z014' AND COD.CODE = B.CODE2) AS MGMT_NO_REQ_YN, G.REMARK , G.VIEW_FLAG
FROM ICOMCOD3 A , ICOMCOD3 B, ICOMBDGT G
FROM ICOMCOD3 A , ICOMCOD3 B, ICOMBDGT G, ICOMCOD3 C
WHERE A.BUYER = #{st_com_code} AND A.CODE1 = #{st_dept_code} AND A.TYPE ='DTOD' AND A.BUYER = B.BUYER AND A.CODE2 = B.CODE1 AND B.TYPE = 'DTOA' AND DECODE(B.FLAG,'Y',DECODE( #{st_dept_code} , B.CODE1,'N','Y'),'N') = 'N' AND B.BUYER = G.BUYER(+) AND B.CODE1 = G.DEPT(+) AND B.CODE2 = G.ACCOUNT_TYPE(+) AND G.FROM_DATE(+) <= TO_CHAR(SYSDATE,'YYYYMMDD') AND G.TO_DATE(+) >= TO_CHAR(SYSDATE,'YYYYMMDD')
AND B.BUYER = C.BUYER AND B.CODE2 = C.CODE2 AND C.TYPE = 'BDCT' AND C.CODE1 = #{st_categ}
) X WHERE 1=1 AND X.DEPT_CODE || ' ' || X.DEPT_NAME LIKE '%' || #{st_budget_dept} || '%' AND X.ACCOUNT_TYPE || ' ' || X.ACCOUNT_NAME LIKE '%' || #{st_account} || '%'
AND X.MNG_DEPT_CD = 'A'
AND X.MNG_DEPT_CD = 'J'
AND X.MNG_DEPT_CD <> 'A'
ORDER BY X.MNG_DEPT_CD, X.DEPT_NAME, X.ACCOUNT_NAME
